-- DATA DUMMY CAPSTONE TOPIK B PostgreSQL
-- SKENARIO: SIMULASI SUKU DINAS PERTAMANAN & HUTAN KOTA DKI JAKARTA
-- Sumber: setup_demo1.sql versi Suku Dinas; seluruh data merupakan simulasi.
-- Nama unit, kode, akun, kegiatan, SP2D, tanggal, nominal dan keterangan dipertahankan.
-- PERINGATAN: menghapus dan membuat ulang tabel realisasi, pagu_akun, satker.
-- Jalankan manual pada database latihan, satu kali saat setup atau saat reset uji.
-- Jangan jalankan dari MainConsole setiap kali aplikasi dibuka.
-- Hasil awal: 12 Satker, 26 pagu, 52 realisasi.

DROP TABLE IF EXISTS realisasi;
DROP TABLE IF EXISTS pagu_akun;
DROP TABLE IF EXISTS satker;

CREATE TABLE satker (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  kode_satker VARCHAR(20) NOT NULL UNIQUE,
  nama_satker VARCHAR(120) NOT NULL
);

CREATE TABLE pagu_akun (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  satker_id BIGINT NOT NULL,
  kode_akun VARCHAR(12) NOT NULL,
  nama_akun VARCHAR(120) NOT NULL,
  tahun_anggaran INT NOT NULL,
  deskripsi_kegiatan VARCHAR(150) NOT NULL,
  nilai_pagu DECIMAL(18,2) NOT NULL,
  CONSTRAINT fk_pagu_satker FOREIGN KEY (satker_id) REFERENCES satker(id)
    ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT uq_pagu UNIQUE (satker_id, kode_akun, tahun_anggaran, deskripsi_kegiatan),
  CONSTRAINT ck_nilai_pagu CHECK (nilai_pagu >= 0)
);

CREATE TABLE realisasi (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  pagu_id BIGINT NOT NULL,
  nomor_sp2d VARCHAR(40) NOT NULL UNIQUE,
  tanggal_realisasi DATE NOT NULL,
  nilai_realisasi DECIMAL(18,2) NOT NULL,
  keterangan VARCHAR(250),
  CONSTRAINT fk_realisasi_pagu FOREIGN KEY (pagu_id) REFERENCES pagu_akun(id)
    ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT ck_nilai_realisasi CHECK (nilai_realisasi > 0)
);

-- Nilai pagu terlampaui harus dicegah di BudgetService (bukan hanya CHECK database).
-- Seluruh akses SQL DARI JAVA menggunakan PreparedStatement.




-- Data awal memakai ID eksplisit; ID berikutnya disetel agar insert baru aman.
ALTER TABLE satker ALTER COLUMN id RESTART WITH 13;
ALTER TABLE pagu_akun ALTER COLUMN id RESTART WITH 27;
ALTER TABLE realisasi ALTER COLUMN id RESTART WITH 53;

-- Pemeriksaan ringkas setelah setup.
SELECT 'satker' AS entitas, COUNT(*) AS jumlah FROM satker
UNION ALL SELECT 'pagu_akun', COUNT(*) FROM pagu_akun
UNION ALL SELECT 'realisasi', COUNT(*) FROM realisasi;
